-- ============================================================================
-- Correção em lote de career_players.club_career — pesquisa ogol.com.br
-- (2026-09-30), ver tooling/esmeraldino_passport/research/_career_players_corrections.json
-- pro detalhe de cada campo e a fonte. Preenche só o que a fonte confirma
-- (appearances/goals), nunca estima; onde a soma das temporadas bate exato
-- com o agregado oficial já existente no projeto, isso é citado na nota de
-- cada entrada como evidência de reconciliação.
--
-- Estratégia: substitui o club_career INTEIRO de cada jogador afetado (mais
-- fácil de auditar que jsonb_set encadeado) com PRÉ-condição comparando
-- com o estado documentado antes da correção.

-- ernando (Ernando)
do $$
declare
  v_current jsonb;
begin
  select club_career into v_current from public.career_players where id = 'ernando';
  if v_current is null then
    raise exception 'career_players.ernando não encontrado — aborta.';
  end if;
  if v_current != '[{"period":"2006-2013","team":"Goiás","appearances":405,"goals":null,"loan":false,"is_goias":true},{"period":"2014-2017","team":"Internacional","appearances":170,"goals":8,"loan":false,"is_goias":false},{"period":"2018","team":"Sport","appearances":32,"goals":0,"loan":true,"is_goias":false},{"period":"2019-2020","team":"Bahia","appearances":65,"goals":4,"loan":false,"is_goias":false},{"period":"2021","team":"Vasco","appearances":27,"goals":0,"loan":false,"is_goias":false},{"period":"2022","team":"Guarani","appearances":16,"goals":1,"loan":false,"is_goias":false}]'::jsonb then
    raise exception 'career_players.ernando.club_career não está no estado esperado antes da correção — aborta pra não sobrescrever uma mudança feita por outro caminho. Atual: %', v_current;
  end if;
end $$;

